from pathlib import Path
import json,subprocess,hashlib,re
root=Path('/tmp/starshine-a4237ca-review')
program='/tmp/starshine-a4237ca-baseline/_build/native/release/build/cmd/cmd.exe'
lanes={'string-gathering':'string-gathering','merge-locals':'merge-locals','dfe':'duplicate-function-elimination','dae2-open':'dae2','dae2-optimizing-closed':'dae2-optimizing'}
rows=[]
for lane,kind in lanes.items():
 for case in sorted((Path('.tmp')/('pass-audit-20261019-comparison-'+lane)/'failures').glob('*')):
  dest=root/'baseline-replays'/lane/(case.name+'.wasm');dest.parent.mkdir(parents=True,exist_ok=True)
  args=[program,str(case/'input.wasm'),'--'+kind,'-o',str(dest)]+(['--closed-world'] if lane.endswith('closed') else [])
  p=subprocess.run(args,check=True,capture_output=True)
  same=dest.read_bytes()==(case/'starshine.raw.wasm').read_bytes()
  metadata=json.loads((case/'failure-metadata.json').read_text())
  entry=metadata.get('genValidManifestEntry') or {}
  row={'lane':lane,'case':case.name,'profile':entry.get('selected_profile'),'case_label':entry.get('profile_case_label'),'baseline_raw_identical':same,'raw_delta':(case/'starshine.raw.wasm').stat().st_size-(case/'binaryen.raw.wasm').stat().st_size,'canonical_delta':(case/'starshine.wasm').stat().st_size-(case/'binaryen.wasm').stat().st_size}
  if lane=='string-gathering':
   def project(s):
    s=re.sub(r'\(else\s*\(nop\)\s*\)','(else)',s);s=re.sub(r'\(else\s*\)','(else)',s);return re.sub(r'\s+',' ',s).strip()
   row['only_empty_else_nops']=project((case/'starshine.wat').read_text())==project((case/'binaryen.wat').read_text())
  rows.append(row)
  assert same,row
(root/'baseline-replays.json').write_text(json.dumps(rows,indent=2))
print('Retained baseline replays:',len(rows),'all raw-byte identical to candidate.')

